/* FitFirst V2 — console building blocks forked from V1 app.js: metric definitions, demo walk-in, help requests,
   new-shop setup guide. The shell, login and Today screen are V2's own (console.js). */
(function () {
  const FF = window.FF, U = FF.ui, esc = FF.esc, $ = FF.$, R = FF.ROLES, ALL = R.ALL, MGR = R.MGR;
  const counts = () => FF.counts();
  /* ---------- metrics (definitions follow SYSTEM_IMPROVEMENT_PLAN §3) ---------- */
  FF.metrics = (days) => {
    const db = FF.db, from = Date.now() - days * FF.DAY, V = db.visits.filter((v) => v.at >= from && v.status !== 'BROWSING' && !v.erased), S = db.sales.filter((s) => s.at >= from);
    const sale = (v) => v.sale && db.sales.find((s) => s.id === v.sale);
    const bought = V.filter((v) => v.status === 'PURCHASED'), recBuy = bought.filter((v) => { const s = sale(v); return s && s.lines.some((l) => l.rec); });
    const agedLines = S.flatMap((s) => s.lines.filter((l) => l.aged).map((l) => ({ l, s }))), agedCleared = FF.sum(agedLines, (x) => x.l.price * x.l.qty - x.l.disc), agedAttr = FF.sum(agedLines.filter((x) => x.s.visit && x.l.rec), (x) => x.l.price * x.l.qty - x.l.disc);
    const agedBuy = (v) => { const s = sale(v); return !!(s && s.lines.some((l) => l.rec && l.aged)); };
    const boostV = V.filter((v) => !v.holdout && v.status !== 'ABANDONED'), holdV = V.filter((v) => v.holdout && v.status !== 'ABANDONED'), rb = boostV.length ? boostV.filter(agedBuy).length / boostV.length : 0, rh = holdV.length ? holdV.filter(agedBuy).length / holdV.length : 0;
    const ffSales = S.filter((s) => s.visit), base = db.sales.filter((s) => !s.visit && s.at < db.settings.pilot.start);
    const picks = V.flatMap((v) => v.picks), n = (f) => picks.filter(f).length;
    const foot = FF.sum(db.baseline.filter((b) => b.kiosk && new Date(b.date).getTime() >= from - FF.DAY), (b) => b.footfall);
    const reasons = FF.groupBy(picks.filter((p) => p.state === 'rejected' && p.reason), (p) => p.reason);
    return { V, S, sessions: V.length, bought: bought.length, recBuy: recBuy.length, agedCleared, agedAttr, rb, rh, nBoost: boostV.length, nHold: holdV.length, lift: rh > 0 && holdV.length >= 20 ? rb / rh - 1 : null,
      basket: ffSales.length ? FF.sum(ffSales, (s) => s.total) / ffSales.length : 0, baseBasket: base.length ? FF.sum(base, (s) => s.total) / base.length : 0, baseN: base.length,
      mins: bought.length ? FF.sum(bought, (v) => v.mins || 0) / bought.length : 0, tried: bought.length ? FF.sum(bought, (v) => v.picks.filter((p) => ['tried', 'rejected', 'bought'].includes(p.state)).length) / bought.length : 0,
      funnel: [['Shown', picks.length], ['Shortlisted', n((p) => p.state !== 'shown')], ['Tried', n((p) => ['tried', 'rejected', 'bought'].includes(p.state))], ['Bought', n((p) => p.state === 'bought')]], footfall: foot, usage: foot ? V.length / foot : null, abandoned: V.filter((v) => v.status === 'ABANDONED').length,
      reasons: Object.entries(reasons).map(([l, a]) => ({ l, v: a.length })).sort((a, b) => b.v - a.v), revenue: FF.sum(S, (s) => s.total) };
  };

  /* Today is V2's own (console.js) */
  FF.act('help-done', (d) => { const h = FF.db.help.find((x) => x.id === d.id); h.done = true; FF.save(); FF.render(); FF.toast('Marked as handled', 'ok'); });
  /* demo helper: create a finished consultation without opening the kiosk */
  FF.simWalkin = (n) => { const r = Math.random, pick = (a) => a[Math.floor(r() * a.length)], dept = pick(['WOMEN', 'WOMEN', 'MEN']); const pr = { label: 'Me', dept, isMinor: false, cats: dept === 'WOMEN' ? pick([['saree'], ['kurti', 'kurta_set', 'anarkali'], ['lehenga']]) : ['kurta_pyjama', 'nehru_jacket'], occasion: pick(['festive', 'wedding', 'festive']), budget: pick([3000, 6000, 12000, 0]), sizes: { ALPHA: pick(['S', 'M', 'L', 'XL']) }, height: pick(['petite', 'average', 'tall']), likes: [], dislikes: [], tone: 3 + Math.floor(r() * 6), undertone: pick(['warm', 'cool', 'neutral']), contrast: pick(['medium', 'high']), method: 'swatch + quiz', goals: dept === 'WOMEN' ? [pick(['balance_hips', 'look_taller', 'streamline_mid', 'define_waist'])] : ['look_taller'], quiz: {} };
    const code = FF.newCode(), holdout = FF.hash(code) % 100 < FF.db.settings.holdout, res = FF.engine.recommend(pr, { holdout }), now = Date.now(); if (res.all.length < 3 && (n || 0) < 12) return FF.simWalkin((n || 0) + 1);
    const v = { id: FF.uid('v'), code, at: now - 4 * 60000, waitingSince: now, channel: pick(['KIOSK', 'QR']), status: 'WAITING', staff: null, holdout, lang: pick(['en', 'gu', 'hi']), profiles: [pr], picks: res.all.map((i) => ({ pid: i.pid, rank: i.rank, profile: 0, state: i.rank <= 2 ? 'shortlisted' : 'shown', boosted: i.boosted, size: i.m.size, sizeKind: i.m.kind, reasons: i.reasons.slice(0, 2).map((x) => ({ k: x.k, v: x.v })), offer: i.offer, age: i.age, S: Math.round(i.S * 100) / 100, talk: FF.engine.talk(i) })), shortlist: res.all.slice(0, 2).map((i) => i.pid), events: [{ at: now - 4 * 60000, type: 'start', text: 'Consultation started' }, { at: now, type: 'handoff', text: 'Handoff code shown' }], rating: null, tryons: 0, tryLimit: FF.db.settings.tryon.perVisit, consent: { personal: true, camera: false } };
    FF.db.visits.push(v); FF.save(); return v; };
  FF.act('sim-walkin', () => { const v = FF.simWalkin(); FF.render(); FF.toast('New shopper waiting · ' + v.code, 'ok'); });

  /* ---------- setup guide (first-run onboarding for a new shop) ---------- */
  const OB = { step: 0, a: {} };
  const OBS = ['Your shop', 'Billing today', 'First stock', 'Team & devices', 'Clearance & pilot', 'Go live'];
  FF.page('onboarding', { title: 'Setup guide', icon: 'flag', roles: MGR, render: () => { const st = FF.store(), s = FF.db.settings, a = OB.a;
    const path = a.sw === 'none' || a.happy === 'no' ? 'B' : a.sw === 'erp' ? 'A' : a.sw ? 'A' : null, lvl = a.sw === 'erp' ? 'L3 cloud connector' : a.sw === 'tally' && a.agent === 'yes' ? 'L2 bridge on the billing PC' : 'L1 daily Excel/CSV export';
    const body = [
      () => `<form data-submit="ob-shop" class="grid g2 stack">${U.field('Shop name', `<input name="name" required value="${esc(st.name)}">`)}${U.field('Area / city', `<input name="area" required value="${esc(st.area)}">`)}${U.field('GSTIN', `<input name="gstin" value="${esc(st.gstin)}" pattern="[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]" data-msg="A GSTIN has 15 characters, e.g. 24ABCDE1234F1Z5">`, 'Leave empty if unregistered')}${U.field('GST registration', `<select name="reg">${[['REGULAR', 'Regular — Tax Invoice'], ['COMPOSITION', 'Composition — Bill of Supply'], ['NONE', 'Unregistered — plain receipt']].map(([v, l]) => `<option value="${v}" ${st.reg === v ? 'selected' : ''}>${l}</option>`).join('')}</select>`)}${U.field('Shopper languages', `<div class="row wrap">${FF.LANGS.map((l) => `<label class="check"><input type="checkbox" name="l_${l[0]}" ${s.langs.includes(l[0]) ? 'checked' : ''}> ${l[1]}</label>`).join('')}</div>`)}${U.field('How shoppers will use FitFirst first', `<select name="mode">${[['ASSISTED', 'Assisted — salesperson’s tablet (recommended for counter service)'], ['QR', 'QR Stylist — shopper’s own phone'], ['KIOSK', 'Kiosk touchscreen']].map(([v, l]) => `<option value="${v}" ${s.mode === v ? 'selected' : ''}>${l}</option>`).join('')}</select>`)}<div><button class="btn btn-p">Save and continue</button></div></form>`,
      () => `<p class="muted small mb16">The discovery questions from the first meeting. The answers decide whether FitFirst connects to the billing software (path A) or becomes it (path B).</p><div class="col gap16">${[['sw', 'Which billing software does the shop use?', [['tally', 'Tally'], ['vyapar', 'Vyapar / Marg / Busy'], ['erp', 'Retail ERP (Ginesys, GoFrugal…)'], ['none', 'None — bill book']]], ['happy', 'Is the owner happy with it?', [['yes', 'Yes'], ['no', 'No — wants one system']]], ['barcode', 'Do garments carry barcode tags?', [['yes', 'Yes'], ['some', 'Some'], ['no', 'No']]], ['export', 'Can it export items with stock and purchase date?', [['yes', 'Yes'], ['unsure', 'Not sure'], ['no', 'No']]], ['agent', 'May we install a small program on the billing PC?', [['yes', 'Yes'], ['no', 'No']]], ['net', 'Internet at the counter?', [['good', 'Reliable'], ['patchy', 'Patchy'], ['no', 'None']]]].map(([k, qn, opts]) => `<div><div class="lbl mb8">${qn}</div>${U.seg('ob-a', opts, a[k], `data-k="${k}"`)}</div>`).join('')}</div>
        ${path ? `<div class="note ${path === 'B' ? '' : 'n-info'} mt24"><b>Suggested: Path ${path} — ${path === 'A' ? 'work with their billing software' : 'FitFirst Billing'}</b><br>${path === 'A' ? `Start at ${lvl}. The cashier types the shopper's FitFirst code into the bill remarks, which works with any software.` : `Start with the counter-sale subset (sale, receipt, UPI QR, WhatsApp e-bill); add GST invoices after the shop's CA has reviewed the templates. Run in parallel with the old system for one week.`}${a.barcode === 'no' ? '<br>No barcodes: FitFirst prints labels during intake.' : ''}${a.net === 'patchy' || a.net === 'no' ? '<br>Weak internet: offline-first billing and offline recommendations matter here.' : ''}</div>` : ''}<div class="row mt24"><button class="btn" data-act="ob-go" data-d="-1">Back</button><button class="btn btn-p" data-act="ob-path" data-p="${path || ''}" ${path ? '' : 'disabled'}>Use this path</button></div>`,
      () => `<p class="muted small mb16">Do not catalogue the whole shop on day one. Start where the owner's money is stuck.</p><div class="grid g3"><div class="card"><h3>1 · Import the item list</h3><p class="small muted mt4">Bring items, stock and 12–24 months of sales history from the billing software, so stock ages are real.</p><a class="btn btn-s mt12" href="#/import">Open import wizard</a></div><div class="card"><h3>2 · Dead-stock sprint</h3><p class="small muted mt4">Photograph the 300 oldest pieces first with full intake (about 3 minutes each).</p><a class="btn btn-s mt12" href="#/intake">Start intake</a></div><div class="card"><h3>3 · Count by size</h3><p class="small muted mt4">A physical count splits “12 kurtas” into sizes. Nothing in the old data can do this for you.</p><a class="btn btn-s mt12" href="#/count">Start a count</a></div></div><div class="row mt24"><button class="btn" data-act="ob-go" data-d="-1">Back</button><button class="btn btn-p" data-act="ob-go" data-d="1">Continue</button></div>`,
      () => `<div class="grid g2 stack"><div class="card"><h3>Team</h3><p class="small muted mt4">${FF.db.staff.filter((x) => x.active).length} people, each with their own PIN — so sales are credited to a name and a leaver's PIN can be switched off.</p><a class="btn btn-s mt12" href="#/settings/staff">Manage staff</a></div><div class="card"><h3>Devices</h3><p class="small muted mt4">${FF.db.devices.filter((x) => x.active).length} enrolled. Each tablet, kiosk and counter is paired with a one-time code and can be revoked if lost.</p><a class="btn btn-s mt12" href="#/settings/devices">Enrol a device</a></div></div><div class="note n-plain mt16">A 10-minute training script for salespeople is in the Pitch kit. Pick one staff champion who owns FitFirst day to day.</div><div class="row mt24"><button class="btn" data-act="ob-go" data-d="-1">Back</button><button class="btn btn-p" data-act="ob-go" data-d="1">Continue</button></div>`,
      () => `<div class="grid g2 stack"><div class="card"><h3>Clearance priority</h3><p class="small muted mt4">How strongly older stock is nudged up — never past a piece that suits the shopper clearly better.</p><div class="mt12">${U.seg('set-lambda', [['off', 'Off'], ['low', 'Low'], ['medium', 'Medium'], ['high', 'High']], s.lambda)}</div></div><div class="card"><h3>Pilot success numbers</h3><p class="small muted mt4">Agree them in writing before go-live. Once locked they cannot be edited.</p><p class="mt8">${s.pilot.basketLift}% basket · ${s.pilot.recConv}% recommended conversion · ${s.pilot.usage}% usage ${s.pilot.locked ? U.badge('Locked', 'ok') : U.badge('Not locked', 'warn')}</p><a class="btn btn-s mt12" href="#/baseline">Open pilot scorecard</a></div></div><div class="row mt24"><button class="btn" data-act="ob-go" data-d="-1">Back</button><button class="btn btn-p" data-act="ob-go" data-d="1">Continue</button></div>`,
      () => { const checks = [['Shop details saved', true], ['Billing path chosen: ' + (s.pos.path === 'B' ? 'FitFirst Billing' : 'their software (' + s.pos.level + ')'), true], ['At least 200 pieces live', FF.db.products.filter((p) => p.status === 'LIVE').length >= 200, FF.db.products.filter((p) => p.status === 'LIVE').length + ' live in this demo'], ['Every salesperson has a PIN', true], ['Kill threshold locked', s.pilot.locked], ['Privacy notice reviewed by a lawyer', false, 'Owner task — not something software can tick'], ['No festival or wedding peak this week', true]]; return `<div class="card pad0">${checks.map(([l, ok, n]) => `<div class="row" style="padding:10px 16px;border-bottom:1px solid var(--line)"><span class="${ok ? 'ok' : 'warn'}">${FF.icon(ok ? 'check' : 'alert')}</span><span class="grow">${esc(l)}${n ? ` <span class="small muted">· ${esc(n)}</span>` : ''}</span></div>`).join('')}</div><div class="row mt24"><button class="btn" data-act="ob-go" data-d="-1">Back</button><button class="btn btn-p" data-act="ob-finish">Mark setup complete</button></div>`; },
    ][OB.step]();
    return `<div class="ph1"><div><h1>Setup guide</h1><p>From a signed pilot to the first shopper, in six steps. ${s.onboarded ? 'This shop finished setup; the guide stays here for reference and for adding a store.' : ''}</p></div></div><div class="stepper">${OBS.map((l, i) => `<span class="${i === OB.step ? 'on' : i < OB.step ? 'done' : ''}"><b>${i < OB.step ? '✓' : i + 1}</b>${l}</span>`).join('')}</div><div class="card">${body}</div>`; } });
  FF.act('ob-go', (d) => { OB.step = FF.clamp(OB.step + Number(d.d), 0, OBS.length - 1); FF.render(); });
  FF.act('ob-a', (d) => { OB.a[d.k] = d.v; FF.render(); });
  FF.act('ob-shop', (f) => { const st = FF.store(), s = FF.db.settings; Object.assign(st, { name: f.name, area: f.area, gstin: f.gstin, reg: f.reg }); s.langs = FF.LANGS.map((l) => l[0]).filter((l) => f['l_' + l]); if (!s.langs.length) s.langs = ['en']; s.mode = f.mode; FF.audit('Updated store details', st.name); FF.save(); OB.step = 1; FF.render(); FF.toast('Saved', 'ok'); });
  FF.act('ob-path', (d) => { FF.db.settings.pos.path = d.p; FF.audit('Chose billing path ' + d.p, 'POS'); FF.save(); OB.step = 2; FF.render(); });
  FF.act('ob-finish', () => { FF.db.settings.onboarded = true; FF.audit('Setup marked complete', 'Store'); FF.save(); FF.toast('Setup complete', 'ok'); FF.go('#/home'); });

})();
